59	/* LVGL 日志的出口**不在这里**（2026-09-25 修正）：
60	 * `lv_nuttx_init()` 内部会 `lv_log_register_print_cb(syslog_print)`，把这里注册过的
61	 * 回调**覆盖掉** —— 所以 UI 层的日志实际由 LVGL 栈自己的回调落到 syslog
62	 * （`apps/graphics/lvgl/lvgl/src/drivers/nuttx/lv_nuttx_entry.c` 的 `syslog_print()`，
63	 * 输出形如 `[LVGL] [User] ( ts, +dt) func: msg file:line`）。
64	 * 那边原来把 `LV_LOG_LEVEL_USER` 映射成 `LOG_CRIT`（整屏红色），已修成 `LOG_INFO`。
65	 * 所以这里**不再注册第二个回调**：一套机制、且 `transfer_ui` / `lvgl_bench` 同样受益。 */
66	
67	static bool wait_for_lcddev(const char * path, int timeout_ms)
68	{
69	    const int step_ms = 100;
70	    int elapsed = 0;
71	
72	    while (elapsed < timeout_ms) {
73	        int fd = open(path, O_RDWR);
74	        if (fd >= 0) {
75	            close(fd);
76	            LV_LOG_INFO("lcd ready: %s (%d ms)", path, elapsed);
77	            return true;
78	        }
79	        usleep(step_ms * 1000);
80	        elapsed += step_ms;
81	    }
82	
83	    LV_LOG_ERROR("lcd not ready: %s (waited %d ms, errno=%d)",
84	        path, timeout_ms, errno);
85	    return false;
86	}
