99	int main(int argc, char * argv[])
100	{
101	    (void)argc;
102	    (void)argv;
103	
104	    map_page_t * page;
105	    bicycle_mtp_ui_t mtp_ui;
106	
107	    if (lv_is_initialized()) {
108	        LV_LOG_ERROR("LVGL already initialized");
109	        return -1;
110	    }
111	
112	    lv_init();
113	
114	    if (!wait_for_lcddev(BICYCLE_LCD_PATH, BICYCLE_LCD_WAIT_MS)) {
115	        return 1;
116	    }
117	
118	    lv_nuttx_dsc_t info;
119	    lv_nuttx_result_t result;
120	    lv_nuttx_dsc_init(&info);
121	    info.fb_path = BICYCLE_LCD_PATH;
122	    lv_nuttx_init(&info, &result);
123	
124	    if (result.disp == NULL) {
125	        LV_LOG_ERROR("display init failed");
126	        return 1;
127	    }
128	
129	    {
130	        lv_obj_t * scr = lv_display_get_screen_active(result.disp);
131	        lv_timer_t * refr;
132	
133	        lv_obj_set_style_bg_color(scr, lv_color_black(), 0);
134	        lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
135	        /* Keep 2SFBL pixels on the panel until splash is ready. */
136	        lv_display_enable_invalidation(result.disp, false);
137	        refr = lv_display_get_refr_timer(result.disp);
138	        if (refr) {
139	            lv_timer_pause(refr);
140	        }
141	    }
142	
143	    lv_display_set_antialiasing(result.disp, true);
144	
145	#if defined(CONFIG_MYVENDOR_LCD_DISP) && CONFIG_MYVENDOR_LCD_DISP
146	    if (myvendor_lcd_disp_register_done_cb(bicycle_lcd_flush_done, result.disp) < 0) {
147	        LV_LOG_ERROR("lcd flush callback failed");
148	        return 1;
149	    }
150	#endif
151	
152	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
153	    bicycle_inval_probe_init(result.disp);
154	#endif
155	
156	#if defined(CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT) && CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT
157	    bicycle_handler_stat_init();
158	#endif
159	    bicycle_c_debug_init();
160	
161	    lv_port_buttons_init();
162	
163	    lvgl_page_init();
164	
165	    if (lvgl_page_open_boot_sequence() != 0) {
166	        LV_LOG_ERROR("lvgl_page_open_boot_sequence failed");
167	        return 1;
168	    }
169	
170	    if (!myvendor_is_factory()) {
171	        startup_page_sync_boot();
172	    }
173	
174	    /* Splash / factory page use compiled-in helm fonts. Paint before TTF / MTP / vmap. */
175	    lv_display_enable_invalidation(result.disp, true);
176	    {
177	        lv_timer_t * refr = lv_display_get_refr_timer(result.disp);
178	        lv_obj_t * scr = lv_display_get_screen_active(result.disp);
179	
180	        if (refr) {
181	            lv_timer_resume(refr);
182	        }
183	        lv_obj_invalidate(scr);
184	        lv_obj_update_layout(scr);
185	    }
186	    lv_refr_now(result.disp);
187	
188	    page = lvgl_page_map();
189	    if (myvendor_is_factory()) {
190	        LV_LOG_INFO("bicycle: factory page (bitmap fonts, no TTF)");
191	    } else if (!page) {
192	        LV_LOG_INFO("bicycle: splash active, LiveMap loads under Startup");
193	    }
194	
195	    myvendor_mtp_owner_reset();
196	    if (myvendor_mtp_init() != 0) {
197	        LV_LOG_WARN("MTP service init failed (MTP disabled?)");
198	    } else if (myvendor_mtp_transfer_begin() != 0) {
199	        LV_LOG_WARN("MTP transfer_begin deferred until host ENUM");
200	    }
201	
202	    bicycle_mtp_ui_init(&mtp_ui);
203	    if (myvendor_is_factory()) {
204	        bicycle_ride_gpx_salvage_dir();
205	    }
206	    lvgl_page_set_app_started(true);
207	
208	    LV_LOG_INFO(myvendor_is_factory()
209	                ? "bicycle started (factory page + MTP + BLE)"
210	                : "bicycle started (lvgl_page + vmap + MTP)");
211	    bicycle_ui_ctl_ready();
212	    bicycle_ui_ctl_sync_state();
213	    if (myvendor_is_factory()) {
214	        myvendor_gnss_ui_ready();
215	#ifdef CONFIG_MYVENDOR_BLE_COMPANION_AUTOSTART
216	        board_ble_companion_start_after_ui();
217	#endif
218	    }
219	    sf32lb_dvfs_hold(SF32LB_DVFS_HOLD_AWAKE);
220	    sf32lb_dvfs_release(SF32LB_DVFS_HOLD_BOOT);
221	
222	#ifndef CONFIG_DISABLE_PTHREAD
223	    pthread_setname_np(pthread_self(), "bicycle_ui");
224	#endif
225	
226	    while (1) {
227	        myvendor_watchdog_ui_beat();
228	#if defined(CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT) && CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT
229	        bicycle_handler_stat_begin();
230	#endif
231	#if defined(CONFIG_MYVENDOR_LCD_DISP) && CONFIG_MYVENDOR_LCD_DISP
232	        myvendor_lcd_disp_poll_recover_ui();
233	#endif
234	        if (myvendor_is_factory()) {
235	#ifdef CONFIG_MYVENDOR_FACTORY_MODE
236	            factory_page_poll_active();
237	#endif
238	        } else {
239	            bicycle_mtp_ui_run(&mtp_ui);
240	            if (lvgl_page_is_usb_transfer()) {
241	                usb_transfer_page_poll_active();
242	            }
243	        }
244	        page = lvgl_page_map();
245	        bicycle_ui_ctl_poll(page);
246	        /* 传感器快照 → runtime：**主骑行页也要看得到 HR/踏频**（以前只有地图页
247	         * 的 render pump 在同步，停在主界面时值一直是 0）。 */
248	        bicycle_runtime_sync_companion_sensors();
249	        /* 演示模式：四步顺序推进（GPX 导航 → 坐标点导航 → 全国跳点 → 换主题）。
250	         * **必须放在传感器同步之后**：演示场景会写假 HR/功率，若先写再同步，
251	         * 无传感器时 `myvendor_sys_sensor_get_try()` 会把它们清回 0，屏幕上看不到。
252	         * 与 ctl 同一个上下文（循环顶、LVGL 刷新之外），未开时是空操作。 */
253	        bicycle_demo_poll();
254	        {
255	#if MYVENDOR_LVGL_STALL_LOG
256	            uint32_t t0 = lv_tick_get();
257	#endif
258	            uint32_t idle = lv_timer_handler();
259	#if MYVENDOR_LVGL_STALL_LOG
260	            uint32_t busy = lv_tick_elaps(t0);
261	
262	            if (busy >= 50u) {
263	                LVGL_STALL("lv_timer_handler %ums idle_ret=%u",
264	                    (unsigned)busy, (unsigned)idle);
265	            }
266	#endif
267	
268	#if defined(CONFIG_MYVENDOR_LCD_DISP) && CONFIG_MYVENDOR_LCD_DISP
269	            myvendor_lcd_disp_poll_recover_ui();
270	#endif
271	
272	            /* 换主题的**重活**放这里 —— 在 `lv_timer_handler()` **之后**，也就是本帧
273	             * 已经画完之后（同样在"LVGL refresh 之外"，安全性与循环顶等价，见
274	             * myvendor_lcd_disp.c 的 recover 注释）。
275	             * 为什么不在循环顶：循环顶做的任何事都会**推迟本帧的刷新** ⇒ 用户点一下
276	             * 「主题」要等重活跑完屏幕才动（现场像"要点两次"）。挪到帧后，可见变化
277	             * 只等"按键回调里的行重画"，① 屏底 ② 页头 ③ 主界面 由这一步补上（晚一帧）。
278	             *   · helm_theme_poll_apply()：写 KV + ①② + 登记 ③ 重建
279	             *   · lv_pm_theme_poll_styles()：页面级主题应用 + LVGL 整树样式重算（1.2~1.5 s） */
280	            helm_theme_poll_apply();
281	            lv_pm_theme_poll_styles();
282	#if defined(CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT) && CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT
283	            bicycle_handler_stat_after_handler(idle, BICYCLE_LOOP_SLEEP_MS);
284	            bicycle_handler_stat_usleep_begin();
285	#endif
286	            bicycle_c_debug_loop(idle);
287	        }
288	        if (page && !lvgl_page_is_usb_transfer()) {
289	            map_page_debug_snap(page);
290	        }
291	        {
292	            uint32_t sleep_ms = BICYCLE_LOOP_SLEEP_MS;
293	
294	            if (myvendor_bicycle_ctl_pending()) {
295	                sleep_ms = 0;
296	            }
297	
298	            usleep((useconds_t)sleep_ms * 1000u);
299	        }
300	#if defined(CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT) && CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT
301	        bicycle_handler_stat_usleep_end();
302	#endif
303	    }
304	
305	    myvendor_mtp_deinit();
306	    lv_nuttx_deinit(&result);
307	    lv_deinit();
308	    return 0;
309	}
