32	static void lvgl_page_on_nav(lv_pm_page_t page, lv_pm_nav_evt_t evt, void * user_data)
33	{
34	    bicycle_page_evt_kind_t kind;
35	
36	    LV_UNUSED(user_data);
37	
38	    if (page == NULL) {
39	        return;
40	    }
41	
42	    switch (evt) {
43	    case LV_PM_NAV_EVT_APPEAR_DONE:
44	        if (page->id == (lv_pm_id)BICYCLE_PM_ID_STARTUP) {
45	            startup_page_sync_boot();
46	        }
47	        kind = BICYCLE_PAGE_EVT_APPEARED;
48	        break;
49	    case LV_PM_NAV_EVT_DISAPPEAR_DONE:
50	        kind = BICYCLE_PAGE_EVT_DISAPPEARED;
51	        break;
52	    default:
53	        return;
54	    }
55	
56	    bicycle_runtime_emit_page_evt((uint8_t)page->id, page->name, kind);
57	}
