108	/**
109	 * @brief 静默 push LiveMap 空壳，再 push Startup splash。
110	 */
111	int lvgl_page_open_boot_sequence(void)
112	{
113	    lv_pm_page_t map;
114	
115	    if (myvendor_is_factory()) {
116	#ifdef CONFIG_MYVENDOR_FACTORY_MODE
117	        return lv_pm_open_page_msg((lv_pm_id)BICYCLE_PM_ID_FACTORY, NULL);
118	#else
119	        return -1;
120	#endif
121	    }
122	
123	    map = live_map_page_def();
124	
125	    /* splash 底下的空壳；vmap / TTF 在白屏事项里再加载。 */
126	    map_page_set_boot_deferred(true);
127	
128	    if (map) {
129	        bicycle_page_anima_apply_silent(map);
130	    }
131	
132	    if (lvgl_page_open_home() != 0) {
133	        map_page_set_boot_deferred(false);
134	        return -1;
135	    }
136	
137	    if (lvgl_page_open_startup() != 0) {
138	        map_page_set_boot_deferred(false);
139	        return -1;
140	    }
141	
142	    return 0;
143	}
