/**
 * @file ui_stubs.c
 * @brief NuttX / 板级 / 数据源的 PC 桩实现。
 *
 * 原则：**只给"能跑起来的最小合理值"**，不模拟真实行为。凡是"看起来像数据"
 * 的东西（速度、心率、卫星数）都集中在这里，方便一眼看出是假的。
 */

#include <stddef.h>
#include <stdint.h>
#include <time.h>

#include "nuttx/clock.h"
#include "nuttx/sched.h"
#include "nuttx/arch.h"

/* ── 时间 ─────────────────────────────────────────────────────── */

clock_t clock_systime_ticks(void)
{
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (clock_t)((int64_t)ts.tv_sec * 1000 + (int64_t)ts.tv_nsec / 1000000);
}

int clock_cpuload(int pid, struct cpuload_s *cpuload)
{
    (void)pid;
    if (!cpuload) {
        return -1;
    }
    /* 固定 25%：负载条有东西动就行，不做真统计 */
    cpuload->total = 1000;
    cpuload->active = 250;
    return 0;
}

/* ── 线程枚举（菜单里的"系统"页） ───────────────────────────────── */

static struct tcb_s s_fake_tcb = { .pid = 1, .adj_stack_size = 8192 };

void nxsched_foreach(nxsched_foreach_cb_t handler, void *arg)
{
    if (handler) {
        handler(&s_fake_tcb, arg);
    }
}

size_t up_check_tcbstack(struct tcb_s *tcb, size_t stack_size)
{
    (void)tcb;
    return stack_size / 3;
}

/* ── diag 服务（状态栏的 BLE 告警用） ───────────────────────────── */

uint32_t myvendor_diag_ble_unhealthy_age_ms(void)
{
    /* 很大的值 = "很久没有不健康了" ⇒ 状态栏不亮告警 */
    return 0xFFFFFFFFu;
}
